-- Bind functions
local function buildKeybind(mod, key)
	if mod == "" then
		return key
	else
		return mod .. " + " .. key
	end
end

local function bindExec(mod, key, cmd, flags)
	hl.bind(buildKeybind(mod, key), hl.dsp.exec_cmd(cmd), flags)
end

local function bindDsp(mod, key, dispatcher, flags)
	hl.bind(buildKeybind(mod, key), dispatcher, flags)
end

local function bindFunc(mod, key, func)
	hl.bind(buildKeybind(mod, key), func)
end

