-- Zoom
bindFunc(mainMod, "Z", function()
	local ZOOM_LEVEL = 2.5
	local MIN_ZOOM = 1
	local current_zoom = hl.get_config("cursor.zoom_factor")
	local target = current_zoom == MIN_ZOOM and ZOOM_LEVEL or MIN_ZOOM
	hl.config({ cursor = { zoom_factor = target } })
end)

