-- Brightness
local function brigthnessControl(mod, key, amount)
	local brightnessNotify =
		[[awk -v cur="$(brightnessctl get)" -v max="$(brightnessctl max)" 'BEGIN { printf("%.0f", cur/max*100) }' | xargs -I{} notify-send -h int:value:{} -h string:synchronous:volume "󰍹 Brightness: {}%"]]
	bindExec(
		mod,
		key,
		"brightnessctl set " .. amount .. "% && " .. brightnessNotify,
		{ repeating = true, locked = true }
	)
end

