-- Volume
local function volumeControl(mod, key, amount)
	local volumeNotify =
		[[wpctl get-volume @DEFAULT_AUDIO_SINK@ | awk '{print $2*100}' | xargs -I{} notify-send -t 1000 -h int:value:{} -h string:synchronous:volume "󰕾 Volume: {}%"]]
	bindExec(
		mod,
		key,
		"wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ " .. amount .. " && " .. volumeNotify,
		{ repeating = true, locked = true }
	)
end

